runtimeEnv.AntiAFKConnection = LocalPlayer.Idled:Connect(function()\n        nudgeInput()\n        pcall(function()\n            if Events and Events:FindFirstChild(\"AFK\") then Events.AFK:FireServer() end\n        end)\n    end)\n\n    runtimeEnv.NexusAntiIdleLoop = true\n    task.spawn(function()\n        while runtimeEnv.NexusAntiIdleLoop do\n            if not alive() then break end\n            task.wait(25 + math.random(0, 15))\n            nudgeInput()\n            pcall(function()\n                if VirtualUser then\n                    VirtualUser:SetKeyDown('0x20')\n                    task.wait(0.05)\n                    VirtualUser:SetKeyUp('0x20')\n                end\n            end)\n            pcall(function()\n                if Events and Events:FindFirstChild(\"AFK\") then Events.AFK:FireServer() end\n            end)\n        end\n    end)\n\n    task.spawn(function()\n        while task.wait(120) do\n            if not alive() then break end\n            pcall(function()\n                game:GetService(\"RunService\").Heartbeat:Wait()\n            end)\n        end\n    end)\n",
